// src/state.ts
import * as path from "path";
import { mkdir, unlink } from "fs/promises";
var NELSON_STATE_FILE = ".opencode/nelson-state.local.json";
async function readState(directory) {
  const statePath = path.join(directory, NELSON_STATE_FILE);
  try {
    const file = Bun.file(statePath);
    if (await file.exists()) {
      return await file.json();
    }
  } catch {}
  return null;
}
async function writeState(directory, state) {
  const statePath = path.join(directory, NELSON_STATE_FILE);
  const dir = path.dirname(statePath);
  await mkdir(dir, { recursive: true });
  await Bun.write(statePath, JSON.stringify(state, null, 2));
}
async function removeState(directory) {
  const statePath = path.join(directory, NELSON_STATE_FILE);
  try {
    const file = Bun.file(statePath);
    if (await file.exists()) {
      await unlink(statePath);
      return true;
    }
  } catch {}
  return false;
}

// src/utils.ts
import * as path2 from "path";
function slugify(text) {
  return text.toLowerCase().trim().replace(/[^\w\s-]/g, "").replace(/\s+/g, "-").replace(/-+/g, "-").replace(/^-+|-+$/g, "").slice(0, 50);
}
async function detectProjectTools(directory) {
  const checkFile = async (filename) => {
    try {
      const file = Bun.file(path2.join(directory, filename));
      return await file.exists();
    } catch {
      return false;
    }
  };
  const [hasJustfile, hasPackageJson, hasMakefile] = await Promise.all([
    checkFile("justfile"),
    checkFile("package.json"),
    checkFile("Makefile")
  ]);
  return { hasJustfile, hasPackageJson, hasMakefile };
}

// src/plan.ts
import * as path3 from "path";
import { mkdir as mkdir2, readdir } from "fs/promises";
var DEFAULT_PLAN_DIR = ".opencode/plans";
var DEFAULT_PLAN_FILE = `${DEFAULT_PLAN_DIR}/PLAN.md`;
function resolvePlanFile(input) {
  if (input.includes("/") || input.endsWith(".md")) {
    return input;
  }
  const slug = slugify(input);
  return `${DEFAULT_PLAN_DIR}/${slug}.md`;
}
async function listPlanFiles(directory) {
  const plansDir = path3.join(directory, DEFAULT_PLAN_DIR);
  try {
    const entries = await readdir(plansDir, { withFileTypes: true });
    return entries.filter((entry) => entry.isFile() && entry.name.endsWith(".md")).map((entry) => ({
      name: entry.name.replace(/\.md$/, ""),
      path: `${DEFAULT_PLAN_DIR}/${entry.name}`
    })).sort((a, b) => a.name.localeCompare(b.name));
  } catch {
    return [];
  }
}
async function readPlanFile(directory, planFile) {
  const planPath = path3.isAbsolute(planFile) ? planFile : path3.join(directory, planFile);
  try {
    const file = Bun.file(planPath);
    if (await file.exists()) {
      return await file.text();
    }
  } catch {}
  return null;
}
async function writePlanFile(directory, planFile, content) {
  const planPath = path3.isAbsolute(planFile) ? planFile : path3.join(directory, planFile);
  const dir = path3.dirname(planPath);
  await mkdir2(dir, { recursive: true });
  await Bun.write(planPath, content);
}
function parsePlanFile(content) {
  const lines = content.split(`
`);
  const tasks = [];
  let title = "";
  let overview = "";
  let completionPromise = null;
  let inOverview = false;
  let currentTask = null;
  let taskDescription = [];
  for (let i = 0;i < lines.length; i++) {
    const line = lines[i];
    const lineNumber = i + 1;
    if (!title && line.match(/^#\s+(.+)/)) {
      title = line.replace(/^#\s+/, "").trim();
      continue;
    }
    const promiseMatch = line.match(/completion[_-]?promise:\s*["']?([^"'\n]+)["']?/i);
    if (promiseMatch) {
      completionPromise = promiseMatch[1].trim();
      continue;
    }
    if (line.match(/^##\s+Overview/i)) {
      inOverview = true;
      continue;
    }
    if (line.match(/^##\s+Tasks/i)) {
      inOverview = false;
      continue;
    }
    if (inOverview && line.trim()) {
      overview += (overview ? `
` : "") + line;
      continue;
    }
    const taskMatch = line.match(/^(?:\d+\.\s+)?-?\s*\[([ xX])\]\s*(?:\*\*)?(.+?)(?:\*\*)?$/);
    if (taskMatch) {
      if (currentTask && currentTask.id) {
        currentTask.description = taskDescription.join(`
`).trim();
        tasks.push(currentTask);
      }
      const isCompleted = taskMatch[1].toLowerCase() === "x";
      const taskTitle = taskMatch[2].trim();
      currentTask = {
        id: `task-${tasks.length + 1}`,
        title: taskTitle,
        description: "",
        status: isCompleted ? "completed" : "pending",
        lineNumber
      };
      taskDescription = [];
      continue;
    }
    if (currentTask && line.match(/^\s{2,}/) && line.trim()) {
      taskDescription.push(line.trim());
    }
  }
  if (currentTask && currentTask.id) {
    currentTask.description = taskDescription.join(`
`).trim();
    tasks.push(currentTask);
  }
  return {
    title,
    overview,
    tasks,
    completionPromise,
    rawContent: content
  };
}
function updateTaskStatus(content, taskId, tasks, newStatus) {
  const task = tasks.find((t) => t.id === taskId);
  if (!task)
    return content;
  const lines = content.split(`
`);
  const line = lines[task.lineNumber - 1];
  const updatedLine = newStatus === "completed" ? line.replace(/\[\s\]/, "[x]") : line.replace(/\[[xX]\]/, "[ ]");
  lines[task.lineNumber - 1] = updatedLine;
  return lines.join(`
`);
}

// src/git.ts
function formatCommitMessage(taskTitle, taskNum) {
  const cleanTitle = taskTitle.replace(/\*\*/g, "").trim();
  const separatorIdx = cleanTitle.indexOf(" - ");
  if (separatorIdx !== -1) {
    const heading = cleanTitle.slice(0, separatorIdx).trim();
    const description = cleanTitle.slice(separatorIdx + 3).trim();
    return {
      subject: `feat(nelson): task ${taskNum} - ${heading}`,
      body: description || null
    };
  }
  return {
    subject: `feat(nelson): task ${taskNum} - ${cleanTitle}`,
    body: null
  };
}
async function createGitCommit(directory, taskTitle, taskNum) {
  const { spawn } = await import("child_process");
  const runCommand = (cmd, args) => {
    return new Promise((resolve) => {
      const proc = spawn(cmd, args, { cwd: directory });
      let stdout = "";
      let stderr = "";
      proc.stdout?.on("data", (data) => stdout += data.toString());
      proc.stderr?.on("data", (data) => stderr += data.toString());
      proc.on("close", (code) => resolve({ code: code ?? 1, stdout, stderr }));
      proc.on("error", () => resolve({ code: 1, stdout, stderr: "Command failed to spawn" }));
    });
  };
  const gitCheck = await runCommand("git", ["rev-parse", "--git-dir"]);
  if (gitCheck.code !== 0) {
    return { success: false, message: "Not a git repository" };
  }
  const statusCheck = await runCommand("git", ["status", "--porcelain"]);
  if (statusCheck.stdout.trim() === "") {
    return { success: false, message: "No changes to commit" };
  }
  const addResult = await runCommand("git", ["add", "-A"]);
  if (addResult.code !== 0) {
    return { success: false, message: `Failed to stage changes: ${addResult.stderr}` };
  }
  const { subject, body } = formatCommitMessage(taskTitle, taskNum);
  const commitArgs = ["commit", "-m", subject];
  if (body) {
    commitArgs.push("-m", body);
  }
  const commitResult = await runCommand("git", commitArgs);
  if (commitResult.code !== 0) {
    return { success: false, message: `Failed to commit: ${commitResult.stderr}` };
  }
  return { success: true, message: `Created commit: ${subject}` };
}
async function markTaskCompleteAndCommit(directory, planFile, taskNum, shouldCommit) {
  const content = await readPlanFile(directory, planFile);
  if (!content) {
    throw new Error(`Plan file not found: ${planFile}`);
  }
  const plan = parsePlanFile(content);
  if (taskNum < 1 || taskNum > plan.tasks.length) {
    throw new Error(`Invalid task number: ${taskNum}`);
  }
  const task = plan.tasks[taskNum - 1];
  const alreadyCompleted = task.status === "completed";
  if (!alreadyCompleted) {
    const updatedContent = updateTaskStatus(content, task.id, plan.tasks, "completed");
    await writePlanFile(directory, planFile, updatedContent);
  }
  let commitResult;
  if (shouldCommit) {
    commitResult = await createGitCommit(directory, task.title, taskNum);
  }
  return { taskTitle: task.title, commitResult };
}

// src/prompts.ts
function generateSingleTaskPrompt(plan, task, taskNum, isLoopMode, projectTools) {
  let prompt = `# ${plan.title || "Project Plan"}

`;
  if (plan.overview) {
    prompt += `## Project Context
${plan.overview}

`;
  }
  if (projectTools) {
    const tools = [];
    if (projectTools.hasJustfile)
      tools.push("`just` (justfile)");
    if (projectTools.hasPackageJson)
      tools.push("`npm`/`bun` (package.json)");
    if (projectTools.hasMakefile)
      tools.push("`make` (Makefile)");
    if (tools.length > 0) {
      prompt += `## Available Tools
This project has: ${tools.join(", ")}

`;
      prompt += `**IMPORTANT**: Use these project tools for build, test, and other operations:
`;
      if (projectTools.hasJustfile) {
        prompt += `- Run \`just\` to see all available tasks, then use \`just <task>\` for build/test/format
`;
      }
      if (projectTools.hasPackageJson) {
        prompt += `- Use \`npm run <script>\` or \`bun run <script>\` for package.json scripts
`;
      }
      if (projectTools.hasMakefile) {
        prompt += `- Use \`make <target>\` for Makefile targets
`;
      }
      prompt += `
`;
    }
  }
  const completedCount = plan.tasks.filter((t) => t.status === "completed").length;
  prompt += `## Progress: ${completedCount}/${plan.tasks.length} tasks complete

`;
  prompt += `### All Tasks
`;
  for (let i = 0;i < plan.tasks.length; i++) {
    const t = plan.tasks[i];
    const checkbox = t.status === "completed" ? "[x]" : "[ ]";
    const current = i === taskNum - 1 ? " \u2190 CURRENT" : "";
    prompt += `${i + 1}. ${checkbox} ${t.title}${current}
`;
  }
  prompt += `
## Current Task: #${taskNum}

`;
  prompt += `**${task.title}**

`;
  prompt += task.description || "No additional description provided.";
  prompt += `

`;
  if (isLoopMode) {
    prompt += `## Instructions

Complete this task thoroughly. When you finish:
1. Verify your work is correct
2. The task will be automatically marked complete
3. A git commit will be created for this task
4. The loop will continue to the next task

Focus ONLY on this task - do not work ahead.
`;
  } else {
    prompt += `## Instructions

Complete this task thoroughly. When you finish:
1. Verify your work is correct
2. The task will be automatically marked complete
3. Review your changes and commit manually when ready
`;
  }
  return prompt;
}

